import{_ as a,c as n,o as t,ag as i}from"./chunks/framework.Vyheyqg9.js";const h=JSON.parse('{"title":"CS-P03: sorting and recursion experiment","description":"","frontmatter":{},"headers":[],"relativePath":"practice/cs-foundations/sorting.md","filePath":"practice/cs-foundations/sorting.md"}'),r={name:"practice/cs-foundations/sorting.md"};function s(o,e,c,l,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="cs-p03-sorting-and-recursion-experiment" tabindex="-1">CS-P03: sorting and recursion experiment <a class="header-anchor" href="#cs-p03-sorting-and-recursion-experiment" aria-label="Permalink to “CS-P03: sorting and recursion experiment”">​</a></h1><p><strong>Learner status: still required.</strong> Prerequisites: CS-P01/P02, <a href="./../../cs-foundations/reasoning-and-recursion.html">recursion/correctness</a> and <a href="./../../cs-foundations/sorting.html">sorting</a>. Use the <a href="./#evidence-for-every-checkpoint">shared evidence record</a>.</p><h2 id="scope-and-deliverable" tabindex="-1"><span class="hub-section-number">1 </span>Scope and deliverable <a class="header-anchor" href="#scope-and-deliverable" aria-label="Permalink to “1 Scope and deliverable”">​</a></h2><p>Implement or independently reconstruct the small last-pivot allocating sorter for dense finite numbers, with a 256-item limit. Count comparisons, maximum recursive depth and cumulative partition entries; define exactly what each counter includes. Compare correctness against numeric native sorting, without assuming its engine complexity. Keep any three-way/in-place variant separate and optional.</p><h2 id="observable-acceptance" tabindex="-1"><span class="hub-section-number">2 </span>Observable acceptance <a class="header-anchor" href="#observable-acceptance" aria-label="Permalink to “2 Observable acceptance”">​</a></h2><ul><li>Output is ascending <strong>and</strong> a permutation, preserving multiplicities; input is unchanged and output is a fresh array even for 0/1 items.</li><li>Empty, singleton, sorted/reversed, duplicate-heavy, all-equal and deterministic generated inputs match the oracle.</li><li>Sorted/equal n-item inputs show n(n−1)/2 comparisons; demonstrate linear call depth with safe small n. Include a balanced fixture and its actual counts.</li><li>Explain base case, partition invariant, induction and decreasing subproblem length.</li><li>Distinguish peak retained partitions, cumulative partition entries, returned arrays and call stack. Counted slots are not measured heap bytes.</li><li>Use equal-key tagged records to expose the last-pivot equality reversal; explain why native stable sorting has a different contract. Do not silently claim generic quicksort stability.</li></ul><h2 id="edge-and-failure-cases" tabindex="-1"><span class="hub-section-number">3 </span>Edge and failure cases <a class="header-anchor" href="#edge-and-failure-cases" aria-label="Permalink to “3 Edge and failure cases”">​</a></h2><p>Reject oversize/sparse/NaN/infinite input under the chosen contract. Demonstrate that “sorted output” alone would let a broken empty-result function pass. Test default string sort against numeric order. Explain why random pivots do not cure all-equal two-way partitions and why a large recursive stress test is not necessary evidence.</p><h2 id="evidence" tabindex="-1"><span class="hub-section-number">4 </span>Evidence <a class="header-anchor" href="#evidence" aria-label="Permalink to “4 Evidence”">​</a></h2><p>Record fixtures, comparison/depth/allocation tables, one failing counterexample/correction, proof and limit rationale. Cross-check recursive and iterative factorial on 0/1/5/100 with exact BigInt and invalid-input cases as a short recursion/iteration checkpoint; count multiplications separately from growing bit cost.</p><h2 id="memoization-extension" tabindex="-1"><span class="hub-section-number">5 </span>Memoization extension <a class="header-anchor" href="#memoization-extension" aria-label="Permalink to “5 Memoization extension”">​</a></h2><p><strong>Optional existing requirement, still required if selected.</strong> Prerequisites: <a href="./../../senior_growth/Other/What_is_memoization.html#correct-keys-ownership-and-invalidation">memoization contracts</a>, equality/ownership and synchronous exceptions. Use the retained synchronous wrapper and compare with uncached results. Verify all falsy outputs, argument types/arity/object identity, receiver identity, NaN hits, ±0 distinction, exception retry, LRU hit promotion/eviction and clear. Demonstrate stale mutation, then fix the key/invalidation contract. Verify bounded Fibonacci 0/1/40 and invalid inputs; record calls, hits/misses and retained-data limits. Async caching is a separate design, not an implied capability.</p><h2 id="execution-extension" tabindex="-1"><span class="hub-section-number">6 </span>Execution extension <a class="header-anchor" href="#execution-extension" aria-label="Permalink to “6 Execution extension”">​</a></h2><p><strong>Optional shared-language requirement, still required if selected.</strong> Prerequisites: <a href="./../../senior_growth/General_ES6/Explain_JavaScript_Code_Execution_177e8106c24d80a0817df62da9bac253.html#worked-bindings-this-and-retained-lexical-state">execution/binding explanation</a>, strict functions/modules and references. Reproduce the supplied binding/this fixture, make two independent counters and explain captured lifetime. Test classic script, CJS and ESM in separate files; a REPL observation is not interchangeable. Retain actual outputs/runtime and a retaining-path explanation for closures. Do not infer physical stack allocation or timely collection from console output.</p><p>The <a href="./retained-exercises.html">original extracted requirements</a> preserve both exercises. They are optional continuations, not two new mandatory CS products.</p>',15)])])}const m=a(r,[["render",s]]);export{h as __pageData,m as default};
